            Node("transfer_radius_sandwich", "transfer radius sandwich", "For the specified parameters, the following hypotheses imply the stated relation: (next : ι → Bool → ι) (allow : ι → Bool → Prop) (x y : ℝ) (hx : 0<x) (hy : 0<y) : min ((y/x)^6) ((y/x)^20) * radius (transfer next allow x) ≤ radius (transfer next allow y) ∧ radius (transfer next allow y) ≤ max ((y/x)^6) ((y/x)^20) * radius (transfer next allow x)", DescribeRole.Theorem, AssessedProvenance.FromRepo()),
            Node("transfer_radius_continuous_pos", "transfer radius continuous pos", "For the specified parameters, the following hypotheses imply the stated relation: (next : ι → Bool → ι) (allow : ι → Bool → Prop) : ContinuousOn (fun z : ℝ => radius (transfer next allow z)) (Set.Ioi 0)", DescribeRole.Theorem, AssessedProvenance.FromRepo()),
            Node("transfer_complex_continuous", "transfer complex continuous", "For the specified parameters, the following hypotheses imply the stated relation: (next : ι → Bool → ι) (allow : ι → Bool → Prop) : Continuous (fun z : ℝ => complexify (transfer next allow z))", DescribeRole.Theorem, AssessedProvenance.FromRepo()),
            Node("transfer_radius_zero", "transfer radius zero", "For the specified parameters, the following hypotheses imply the stated relation: (next : ι → Bool → ι) (allow : ι → Bool → Prop) : radius (transfer next allow 0) = 0", DescribeRole.Theorem, AssessedProvenance.FromRepo()),
            Node("transfer_radius_continuous_zero", "transfer radius continuous zero", "For the specified parameters, the following hypotheses imply the stated relation: (next : ι → Bool → ι) (allow : ι → Bool → Prop) : ContinuousAt (fun z : ℝ => radius (transfer next allow z)) 0", DescribeRole.Theorem, AssessedProvenance.FromRepo()),
